class Solution:
    def maximumAmount(self, coins):
        m, n = len(coins), len(coins[0])
        INF = -10**18
        # dp[i][j][k]: max coins at (i,j) having used k neutralizations (k=0,1,2)
        dp = [[[INF] * 3 for _ in range(n)] for __ in range(m)]

        # initialize start cell (0,0)
        start = coins[0][0]
        if start >= 0:
            dp[0][0][0] = start
        else:
            # use a neutralization if possible
            dp[0][0][1] = 0          # neutralize robber
            dp[0][0][0] = start      # don't neutralize

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                val = coins[i][j]
                for k in range(3):
                    best = INF
                    # from top
                    if i > 0:
                        best = max(best, dp[i-1][j][k])
                    # from left
                    if j > 0:
                        best = max(best, dp[i][j-1][k])
                    if best == INF:
                        continue
                    # don't neutralize
                    nd = best + val
                    dp[i][j][k] = max(dp[i][j][k], nd)
                    # neutralize if robber and we have capacity
                    if val < 0 and k < 2:
                        nd2 = best  # robber does not affect coins
                        dp[i][j][k+1] = max(dp[i][j][k+1], nd2)

        # answer is max over using 0,1,2 neutralizations at destination
        return max(dp[m-1][n-1])

