class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        total = 0
        # Count substrings of length 1 with non-zero digit
        for i, ch in enumerate(s):
            if ch != '0':
                total += 1
        # For substrings of length >=2, only last digit matters
        for i in range(1, n):
            d = int(s[i])
            if d == 0:
                continue
            total += i  # all possible start positions before i
