            cost = 0 if ord(caption[0]) - ord('a') == c else 1
            dp[1][1][c] = (cost, None, None)
        # transitions
        for i in range(1, n):
            for k in (1, 2):
                for c in range(26):
                    cur_cost, _, _ = dp[i][k][c]
                    if cur_cost == INF:
                        continue
                    for nc in (c-1, c+1):
                        if 0 <= nc < 26:
                            add = 0 if ord(caption[i]) - ord('a') == nc else 1
                            ncost = cur_cost + add
                            if nc == c:
