class Solution:
    def countPartitions(self, nums: List[int]) -> int:
        total = sum(nums)
        left = 0
        count = 0
        # iterate through possible partition points
        for i in range(len(nums) - 1):
            left += nums[i]
            right = total - left
            if (left - right) % 2 == 0:
                count += 1
        return count

