class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if k > n:
            return -1

        # Count how many k-length subarrays each value appears in
        cnt = defaultdict(int)
        for i in range(n - k + 1):
            seen = set()
            for j in range(i, i + k):
                val = nums[j]
                if val not in seen:
                    cnt[val] += 1
                    seen.add(val)

        # Find the largest value that appears in exactly one subarray
        answer = -1
        for val, c in cnt.items():
            if c == 1 and val > answer:
                answer = val
        return answer

class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        rows = len(grid)
        cols = len(grid[0]) if rows else 0
        result = []
        left_to_right = True
        for i in range(rows):
            if left_to_right:
                for j in range(cols):
                    if (j % 2) == 0:
                        result.append(grid[i][j])
            else:
                for j in range(cols - 1, -1, -1):
                    if ((cols - 1 - j) % 2) == 0:
                        result.append(grid[i][j])
            left_to_right = not left_to_right
        return result

class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        if k > n:
            return False
        i = 0
        while i < n:
            j = i + 1
            while j < n and s[j] == s[i]:
                j += 1
            run_len = j - i
            if run_len >= k:
                # possible start positions for length k substrings within this run
                start_min = i
                start_max = j - k
                for start in range(start_min, start_max + 1):
                    # check left neighbor
                    if start > 0 and s[start - 1] == s[start]:
                        continue
                    # check right neighbor
                    if start + k < n and s[start + k] == s[start]:
                        continue
                    return True
            i = j
        return False

