    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        # online status: True if online, False if offline
        online = [True] * numberOfUsers
        # store offline end time for each user, None if currently online
        offline_end = [None] * numberOfUsers

        # Since events are given in chronological order and same timestamps are processed
        # with status changes before messages, we can process sequentially.
        for ev in events:
            typ, timestamp_str, data = ev
            timestamp = int(timestamp_str)

            if typ == "OFFLINE":
                uid = int(data)
                online[uid] = False
                offline_end[uid] = timestamp + 60
            else:  # MESSAGE
                token = data
                if token == "ALL":
                    for uid in range(numberOfUsers):
                        mentions[uid] += 1
                elif token == "HERE":
                    for uid in range(numberOfUsers):
                        if online[uid]:
                            mentions[uid] += 1
                else:
                    # parse id mentions, may contain duplicates
                    parts = token.split()
                    for part in parts:
                        if part.startswith("id"):
                            uid = int(part[2:])
                            mentions[uid] += 1
