class Solution:
    def maxSum(self, nums, k, m):
        n = len(nums)
        # prefix sums
        pref = [0] * (n + 1)
        for i in range(n):
            pref[i + 1] = pref[i] + nums[i]

        # best[i] = max sum of a subarray ending at i with length >= m
        best = [-10**18] * n
        for i in range(m - 1, n):
            best[i] = pref[i + 1] - pref[i + 1 - m]
            if i >= m:
                best[i] = max(best[i], best[i - 1] + nums[i])

        # dp[t][i] = max sum using t subarrays considering first i elements (i is index of last element considered)
        dp = [[-10**18] * n for _ in range(k + 1)]
        for i in range(n):
            dp[0][i] = 0  # zero subarrays give sum 0

        for t in range(1, k + 1):
            max_prev = -10**18
            for i in range(m - 1, n):
                # option to end the t-th subarray at i
                if i - 1 >= 0:
                    max_prev = max(max_prev, dp[t - 1][i - 1])
                else:
                    max_prev = max(max_prev, 0 if t == 1 else -10**18)
                dp[t][i] = max(dp[t][i - 1] if i > 0 else -10**18, max_prev + best[i])

        return dp[k][n - 1]

class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total = 0
        for i, val in enumerate(nums):
            left_idx = i - k
            right_idx = i + k
            left_ok = left_idx < 0 or val > nums[left_idx]
            right_ok = right_idx >= n or val > nums[right_idx]
            if left_ok and right_ok:
                total += val
        return total

