class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total = 0

        # Helper to compute contributions for a given window size
        def contributions(window):
            contrib = 0
            maxdq = deque()  # indices of potential maximums
            mindq = deque()  # indices of potential minimums
            for i, v in enumerate(window):
                # Maintain max deque (decreasing values)
                while maxdq and window[maxdq[-1]] <= v:
                    maxdq.pop()
                maxdq.append(i)
                # Remove out-of-window indices
                if maxdq[0] <= i - k:
                    maxdq.popleft()

                # Maintain min deque (increasing values)
                while mindq and window[mindq[-1]] >= v:
                    mindq.pop()
                mindq.append(i)
                if mindq[0] <= i - k:
                    mindq.popleft()

                # When we have a full window, add max+min
                if i >= k - 1:
                    contrib += window[maxdq[0]] + window[mindq[0]]
            return contrib

        # Process windows of size exactly k
        if k > 0:
            for start in range(0, n - k + 1):
                total += contributions(nums[start:start + k])

        # Process windows of sizes 1 to k-1
        for size in range(1, k):
            for start in range(0, n - size + 1):
                window = nums[start:start + size]
                # For size 1, max and min are the same element
                if size == 1:
                    total += 2 * window[0]
                else:
                    # Compute max and min directly for small windows
                    mx = max(window)
                    mn = min(window)
                    total += mx + mn

        return total

