class Solution:
    def findValidPair(self, s: str) -> str:
        # Count occurrences of each digit
        counts = {}
        for ch in s:
            counts[ch] = counts.get(ch, 0) + 1

        # Traverse adjacent pairs
        for i in range(len(s) - 1):
            a, b = s[i], s[i + 1]
            if a == b:
                continue
            if counts.get(a, 0) == int(a) and counts.get(b, 0) == int(b):
                return a + b
        return ""

