class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        positions = {}
        for i, v in enumerate(nums):
            positions.setdefault(v, []).append(i)

        ans = []
        for q in queries:
            v = nums[q]
            pos_list = positions[v]
            if len(pos_list) == 1:
                ans.append(-1)
                continue

            idx = bisect.bisect_left(pos_list, q)
            # successor
            if idx < len(pos_list):
                succ = pos_list[idx]
                if succ == q:
                    if idx + 1 < len(pos_list):
                        succ = pos_list[idx + 1]
                    else:
                        succ = pos_list[0]
                d1 = (succ - q) % n
            else:
                succ = pos_list[0]
                d1 = (succ - q) % n

            # predecessor
            if idx > 0:
                pred = pos_list[idx - 1]
                if pred == q:
                    if idx - 2 >= 0:
                        pred = pos_list[idx - 2]
                    else:
                        pred = pos_list[-1]
                d2 = (q - pred) % n
            else:
                pred = pos_list[-1]
                d2 = (q - pred) % n

            ans.append(min(d1, d2))
        return ans

class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # Build prefix sum of differences to k
        diff = [0] * (n + 1)
        for i, v in enumerate(nums):
            diff[i + 1] = diff[i] + (k - v)
        # diff[i] = sum_{t=0}^{i-1} (k - nums[t])
        # For subarray [l, r], total addition needed to make all elems == k is:
        # need = (r-l+1)*k - sum_{t=l}^{r} nums[t] = diff[r+1] - diff[l]
        # We need need == 0 -> diff[r+1] == diff[l]
        # So we need the longest subarray where prefix sums are equal.
        first_occurrence = {}
        max_len = 0
        for i, val in enumerate(diff):
            if val in first_occurrence:
                length = i - first_occurrence[val]
                if length > max_len:
                    max_len = length
            else:
                first_occurrence[val] = i
        # max_len is the largest number of elements we can turn into k
        # plus the existing ks outside the subarray.
        existing_k = sum(1 for v in nums if v == k)
        return existing_k + max_len

class Solution:
    def maxDifference(self, s: str) -> int:
        freq = {}
        for ch in s:
            freq[ch] = freq.get(ch, 0) + 1

        odd_freqs = []
        even_freqs = []
        for f in freq.values():
            if f % 2:
                odd_freqs.append(f)
            else:
                even_freqs.append(f)

        # Since the problem guarantees at least one odd and one even frequency,
        # both lists will be non‑empty.
        max_odd = max(odd_freqs)
        min_even = min(even_freqs)

        return max_odd - min_even

