class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        # Map each divisor to the smallest index of an element having that divisor
        divisor_to_index = {}
        for idx, val in enumerate(elements):
            d = 1
            while d * d <= val:
                if val % d == 0:
                    if d not in divisor_to_index or idx < divisor_to_index[d]:
                        divisor_to_index[d] = idx
                    other = val // d
                    if other != d and (other not in divisor_to_index or idx < divisor_to_index[other]):
                        divisor_to_index[other] = idx
                d += 1

        # Assign elements to groups
        result = []
        for g in groups:
            if g in divisor_to_index:
                result.append(divisor_to_index[g])
            else:
                result.append(-1)
        return result

