class SegmentTree:
    def __init__(self, data):
        n = len(data)
        self.N = 1
        while self.N < n:
            self.N <<= 1
        self.size = self.N
        self.tree = [float('inf')] * (2 * self.N)
        for i in range(n):
            self.tree[self.N + i] = data[i]
        for i in range(self.N - 1, 0, -1):
            self.tree[i] = min(self.tree[2 * i], self.tree[2 * i + 1])

    def update(self, idx, value):
        i = self.N + idx
        self.tree[i] = value
        i >>= 1
        while i:
            self.tree[i] = min(self.tree[2 * i], self.tree[2 * i + 1])
            i >>= 1

    def query_min(self):
        return self.tree[1]

