class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        n = len(s)
        # Record first and last occurrence of each character
        first = {}
        last = {}
        for i, ch in enumerate(s):
            if ch not in first:
                first[ch] = i
            last[ch] = i

        # Build intervals for characters that appear more than once
        intervals = []
        for ch in first:
            if first[ch] != last[ch]:  # appears at least twice
                intervals.append((first[ch], last[ch]))

        # Merge overlapping intervals
        intervals.sort()
        merged = []
        for start, end in intervals:
            if not merged or start > merged[-1][1]:
                merged.append([start, end])
            else:
                merged[-1][1] = max(merged[-1][1], end)

        # Count pure single-character intervals (characters that appear exactly once)
        single_counts = {}
        for i, ch in enumerate(s):
            if first[ch] == last[ch]:  # appears exactly once
                single_counts[ch] = single_counts.get(ch, 0) + 1

        # For each merged interval, count distinct characters that appear only within it
        interval_counts = []
        for start, end in merged:
            distinct_in_interval = set(s[start:end + 1])
            count = 0
            for ch in distinct_in_interval:
                if first[ch] >= start and last[ch] <= end:
                    count += 1
            interval_counts.append(count)

        # Sort interval capacities descending and try to allocate k substrings
        interval_counts.sort(reverse=True)

        # Use single character occurrences as additional capacity
        singles = sum(single_counts.values())
        total_capacity = singles + sum(interval_counts)

        return total_capacity >= k

