class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        # Compute Manhattan distance matrix
        n = len(points)
        dist = [[0] * n for _ in range(n)]
        for i in range(n):
            xi, yi = points[i]
            for j in range(i + 1, n):
                xj, yj = points[j]
                d = abs(xi - xj) + abs(yi - yj)
                dist[i][j] = dist[j][i] = d

        # Helper to check if we can pick k points with min distance >= d
        def can_place(d: int) -> bool:
            # Order points by degree (fewest neighbors first) to improve backtracking
            degrees = [sum(1 for j in range(n) if i != j and dist[i][j] < d) for i in range(n)]
            order = sorted(range(n), key=lambda x: degrees[x])

            selected = []

            def backtrack(idx: int) -> bool:
                if len(selected) == k:
                    return True
                if idx == n:
                    return False
                # Prune if not enough points left
                if len(selected) + (n - idx) < k:
                    return False
                p = order[idx]
                # Try to include p
                ok = True
                for q in selected:
                    if dist[p][q] < d:
                        ok = False
                        break
                if ok:
                    selected.append(p)
                    if backtrack(idx + 1):
                        return True
                    selected.pop()
                # Try without p
                return backtrack(idx + 1)

            return backtrack(0)

        # Binary search over possible distances
        low, high = 0, 2 * side
        while low < high:
            mid = (low + high + 1) // 2
            if can_place(mid):
                low = mid
            else:
                high = mid - 1
        return low

