    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        # dp[i][j][c] = max LPS length in s[i..j] using exactly c operations
        dp = [[[0] * (k + 1) for _ in range(n)] for _ in range(n)]

        for i in range(n):
            for c in range(k + 1):
                dp[i][i][c] = 1  # single character palindrome

        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                for c in range(k + 1):
                    # Option 1: skip left character
                    best = dp[i + 1][j][c]
                    # Option 2: skip right character
                    if dp[i][j - 1][c] > best:
                        best = dp[i][j - 1][c]

                    # Option 3: match without change if possible
                    if s[i] == s[j]:
                        cand = dp[i + 1][j - 1][c] + 2
                        if cand > best:
                            best = cand

                    # Option 4: match by changing one side (cost 1)
                    if c >= 1:
                        cand = dp[i + 1][j - 1][c - 1] + 2
                        if cand > best:
                            best = cand

                    # Option 5: match by changing both sides (cost 2)
                    if c >= 2:
                        cand = dp[i + 1][j - 1][c - 2] + 2
                        if cand > best:
                            best = cand

                    dp[i][j][c] = best

        # The answer is the maximum length achievable with up to k operations
        return max(dp[0][n - 1])

