class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        if n == 0:
            return 0

        # Convert each property list to a set of distinct values
        sets = [set(row) for row in properties]

        # Build adjacency list
        adj = [[] for _ in range(n)]
        for i in range(n):
            for j in range(i + 1, n):
                # Count distinct common elements
                common = len(sets[i] & sets[j])
                if common >= k:
                    adj[i].append(j)
                    adj[j].append(i)

        # DFS to count connected components
        visited = [False] * n
        def dfs(u: int):
            stack = [u]
            visited[u] = True
            while stack:
                node = stack.pop()
                for nei in adj[node]:
                    if not visited[nei]:
                        visited[nei] = True
                        stack.append(nei)

        components = 0
        for i in range(n):
            if not visited[i]:
                components += 1
                dfs(i)

        return components

