    def is_cube(val: int):
        if val < 0:
            return None
        # integer cube root via binary search
        lo, hi = 0, int(round(val ** (1/3))) + 2
        if hi < 0:
            hi = 0
        while lo <= hi:
            mid = (lo + hi) // 2
            c = mid * mid * mid
            if c == val:
                return mid
            if c < val:
                lo = mid + 1
            else:
                hi = mid - 1
        return None

    # iterate over possible y
    # limit y up to cube_root(N) because (y+1)^3 - y^3 = 3y^2+3y+1 > N when y large enough
    y_limit = int(round(N ** (1/3))) + 2
    for y in range(1, y_limit + 1):
        y3 = y * y * y
        x3 = N + y3
        x = is_cube(x3)
        if x is not None and x > 0:
            # ensure positive x,y and x^3 - y^3 == N
            if x * x * x - y3 == N:
                print(f"{x} {y}")
                return
    print("-1")

