        nodes.add(sc)
        nodes.add(tc)
        graph.setdefault(sc, set()).add(tc)
        indeg[tc] = indeg.get(tc, 0) + 1
        indeg.setdefault(sc, indeg.get(sc, 0))

    # Detect cycles using Kahn's algorithm
    from collections import deque
    q = deque([node for node in nodes if indeg.get(node, 0) == 0])
    visited = set()
    while q:
        u = q.popleft()
        visited.add(u)
        for v in graph.get(u, []):
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)

    if len(visited) != len(nodes):
        # There is a cycle, transformation impossible
        print(-1)
        return

    # Count number of edges (required transformations)
    edge_count = sum(len(vs) for vs in graph.values())
    print(edge_count)

