MOD = 998244353

def solve():
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return
    W, H, L, R, D, U = map(int, data)

    # Determine the maximum n needed for factorials
    max_n = max(W, H) + max(R - L, U - D) + 5
    if max_n < 0:
        max_n = 0

    # Precompute factorials and inverse factorials
    fact = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (max_n + 1)
    inv_fact[max_n] = pow(fact[max_n], MOD - 2, MOD)
    for i in range(max_n, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def comb(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD

    total = 0
    # Sum over possible starting x0 and y0
    for x0 in range(W + 1):
        if L <= x0 <= R:
            a = 0
        else:
            a = min(abs(x0 - L), abs(x0 - R))
        # Number of ways to move right a steps (to exit the forbidden x-range)
        ways_x = comb(a + (W - x0), a) if a <= W - x0 else 0

        for y0 in range(H + 1):
            if D <= y0 <= U:
                b = 0
            else:
                b = min(abs(y0 - D), abs(y0 - U))
            # Number of ways to move up b steps (to exit the forbidden y-range)
            ways_y = comb(b + (H - y0), b) if b <= H - y0 else 0

            total = (total + ways_x * ways_y) % MOD

    print(total)

